import { createHash } from "node:crypto";
import { gunzipSync } from "node:zlib";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname } from "node:path";

const EXPECTED = {
  "package.json": "0ec886732e9ebd75a6ddb781520c55efce797c79e948b09620fa5b7b1d0f23f5",
  "app.js": "03c182ff6e63d08698d1a8385cf9e5e77267d396506e5fa2c2a6bfb918eea4c4",
  "index.html": "57a7297eaab380b334ac404ff21deb3a45e6477910dc2fe1a59197c6a3608abe",
  "service-worker.js": "841e545452a634cded823a3688c4b6521ae5f89737d0d55905842e51bfbbb272",
  "scripts/build-static.mjs": "f72486a4e083e68cf6f22672a0f56da671ebcb4fcdf67deaafdb603afb73d3b1"
};
const PAYLOAD = "";

for (const [file, expectedHash] of Object.entries(EXPECTED)) {
  const source = await readFile(file);
  const actualHash = createHash("sha256").update(source).digest("hex");
  if (actualHash !== expectedHash) {
    throw new Error(`2B2 wurde aus Sicherheitsgründen abgebrochen: ${file} entspricht nicht dem geprüften 4.5.3-Ausgangsstand. Erwartet ${expectedHash.slice(0, 12)}, gefunden ${actualHash.slice(0, 12)}.`);
  }
}

const files = JSON.parse(gunzipSync(Buffer.from(PAYLOAD, "base64")).toString("utf8"));
for (const [file, content] of Object.entries(files)) {
  await mkdir(dirname(file), { recursive: true });
  await writeFile(file, content, "utf8");
  console.log(`✓ ${file}`);
}

console.log("✓ Entenarchiv 4.5.3 DOM Lazy-Mount 2B2 wurde exakt auf den geprüften Stand geschrieben.");
